function onSay(player, words, param)
    player:sendTextMessage(MESSAGE_STATUS_CONSOLE_BLUE,"Commands:\n!leave - leave dungeon, goblin island or Rift.\n!info - show you or target more information about attributes. !info PLAYER_NAME to check other player.\n!damageinfo - show more information about damage done, damage taken and healin done on channel More Info. Reuse disables features.\n!moreinfomonster - when you click monster show more information about monster like damage,hp,attack etc. Reuse disables features.\n!showanimation - show animated text after cast passive ability. Reuse disables features.\n!moreinfo - show more information about gold, exp, loot etc. after kill monster this information you can find on channel More Info. Reuse disables features.\n!stats - show you highest damage done.\n!bank !bank balance - you can check you balance account.\n!points - show you Online Points count.\n!autoloot - autoloot commands.\n!spells - shows available spells.\n!name - change name requires an item from the store.\n!uptime - shows how much time has passed since the last restart.\n!deathlist\n!kills\n!online\n!serverinfo\n!buyhouse\n!sellhouse\n!leavehouse")
      return false
    end
